			if = {
				limit = {
					owner = {
						NOT = { has_country_flag = cybernetic_creed_general }
					}
				}
				situation_event = {
					id = machine_age.1090
				}
			}
			if = {
				limit = {
					owner = {
						has_country_flag = cybernetic_creed_general
					}
				}
