					id = machine_age.1100
				}
			}
			owner = {
				set_country_flag = cyber_creed_advanced_government
				advanced_authority_refresh = yes
			}
		}
	}
	stages = {
		stage_1 = {
			icon = GFX_situation_stage_1
			icon_background = GFX_situation_stage_frame_blue
